#include "evaluator.h"
#include "parser.h"
#include <stdio.h>
#include <stdlib.h>
static char *read_file(const char *path, size_t *length) { FILE *f = fopen(path, "rb"); if (!f) return NULL; if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; } long n = ftell(f); if (n < 0 || fseek(f, 0, SEEK_SET) != 0) { fclose(f); return NULL; } char *s = malloc((size_t)n + 1U); if (!s) { fclose(f); return NULL; } size_t got = fread(s, 1, (size_t)n, f); fclose(f); if (got != (size_t)n) { free(s); return NULL; } s[n] = '\0'; if (length) *length = (size_t)n; return s; }
int main(int argc, char **argv) { if (argc != 2) { fprintf(stderr, "Usage: %s <source-file>\n", argv[0]); return 1; } size_t length; char *source = read_file(argv[1], &length); if (!source) { perror(argv[1]); return 1; } Parser parser; parser_init(&parser, source, length); AstNode *program = parser_parse(&parser); if (!program) { fprintf(stderr, "Parse error: %s\n", parser_error(&parser)); free(source); return 1; } Environment *env = env_new(); if (!env) { ast_free(program); free(source); return 1; } Value result = eval_ast(env, program); print_value(&result); putchar('\n'); value_free(&result); env_free(env); ast_free(program); free(source); return 0; }
